"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6139],{56139:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-sentyabr-2026-toplivo","locale":"es","title":"El combustible caro lleva la inflaci\xf3n estadounidense al 3,7% y arrastra otros precios","description":"En septiembre de 2026, la inflaci\xf3n estadounidense sube al 3,7% y la subyacente al 2,6%. C\xf3mo se propaga el combustible caro y qu\xe9 muestran los datos rusos.","blocks":[{"id":"b001","kind":"paragraph","text":"En septiembre de 2026 los precios estadounidenses aumentaron un 3,7% anual, frente al 3,4% de agosto y al 3,6% previsto. El avance mensual fue del 0,6%, m\xe1s de la mitad por gasolina: +9,1% mensual y +34,2% anual. La energ\xeda total subi\xf3 un 20,4% interanual. Tambi\xe9n se aceler\xf3 la subyacente, sin alimentos y energ\xeda: 2,6%, frente al 2,4% de agosto y al 2,5% esperado."},{"id":"b002","kind":"paragraph","text":"As\xed se propaga el combustible. Una panader\xeda reparte en su furgoneta; al subir el di\xe9sel a\xf1ade un recargo. Unos meses despu\xe9s, la tienda lo incorpora al pan; despu\xe9s suben la cafeter\xeda que lo compra y el taxi del cocinero. Son efectos secundarios: un shock se extiende a precios sin v\xednculo directo. El Libro Beige de la Fed menciona petr\xf3leo caro en los 12 distritos y quejas por di\xe9sel y recargos en toda la cadena de suministro."},{"id":"b003","kind":"paragraph","text":"Es una mala se\xf1al para la Fed. El tipo est\xe1 en el 3,75–4%, tras subir un cuarto de punto en septiembre. Austan Goolsbee calific\xf3 el informe de desalentador: la inflaci\xf3n de servicios supera el 5% y apenas baja. La probabilidad de subir el 27–28 de octubre pas\xf3 del 21,6% al 32,7%. El d\xf3lar avanz\xf3 frente a otras monedas y las acciones cayeron; el S&P 500 perdi\xf3 un 1,11%."},{"id":"b004","kind":"paragraph","text":"En Rusia, el combustible tambi\xe9n sube m\xe1s que los dem\xe1s precios, por interrupciones y reparaciones de refiner\xedas. Si pasa al transporte, encarecer\xe1 otros bienes. Desde enero hasta el 12 de octubre, la gasolina subi\xf3 un 21,4%; el di\xe9sel, un 13,5%; y los precios generales, un 6,1%. Del 6 al 12 de octubre, la inflaci\xf3n semanal baj\xf3 al 0,11% tras el salto del 0,96% por tarifas p\xfablicas, pero los alimentos subieron un 0,21% y los huevos un 2,4%."},{"id":"b005","kind":"paragraph","text":"El Banco de Rusia prev\xe9 un 6–7% al cierre de 2026. Para no superar el 7%, los precios solo pueden crecer otro 0,85% (1,07 / 1,061). Son cerca del 0,07% semanal, menos que el \xfaltimo 0,11%. Los analistas encuestados esperan un 7,1%. El regulador publicar\xe1 su previsi\xf3n y decisi\xf3n de tipos el 23 de octubre."},{"id":"b006","kind":"paragraph","text":"Si los efectos secundarios son d\xe9biles, la inflaci\xf3n semanal volver\xe1 al 0,07% o menos y habr\xe1 motivos para considerar recortes. Si transporte, servicios y alimentos siguen a la gasolina, el 14% durar\xe1 m\xe1s: cr\xe9ditos caros y dep\xf3sitos bien remunerados."},{"id":"b007","kind":"heading","text":"\xbfPor qu\xe9 creci\xf3 la inflaci\xf3n estadounidense en septiembre de 2026?"},{"id":"b008","kind":"paragraph","text":"Sobre todo por la gasolina, que subi\xf3 un 9,1% mensual y un 34,2% anual, aportando m\xe1s de la mitad del avance mensual. La subyacente tambi\xe9n pas\xf3 del 2,4% al 2,6%. Las empresas citan recargos de combustible en toda la cadena y algunas tambi\xe9n aranceles de importaci\xf3n."},{"id":"b009","kind":"heading","text":"\xbfSubir\xe1 la Fed los tipos por la inflaci\xf3n?"},{"id":"b010","kind":"paragraph","text":"No est\xe1 decidido. Tras el informe, el mercado asignaba un 32,7% a una subida el 27–28 de octubre, frente al 21,6% previo. El tipo actual es del 3,75–4%."},{"id":"b011","kind":"heading","text":"\xbfCumplir\xe1 la inflaci\xf3n rusa la previsi\xf3n de 2026?"},{"id":"b012","kind":"paragraph","text":"Desde enero hasta el 12 de octubre los precios subieron un 6,1%. Para no rebasar el 7%, techo de la previsi\xf3n, solo pueden avanzar otro 0,85% hasta diciembre. Los analistas esperan un 7,1% y el Banco de Rusia actualizar\xe1 su pron\xf3stico el 23 de octubre."}],"sources":[{"label":"La inflaci\xf3n repunta en septiembre por la energ\xeda estadounidense","url":"https://finance.yahoo.com/economy/articles/inflation-surged-september-u-energy-125137111.html"},{"label":"Las empresas advierten a la Fed del traslado del combustible a los precios","url":"https://finance.yahoo.com/economy/policy/articles/higher-fuel-costs-lead-price-192929072.html"},{"label":"Goolsbee califica de desalentador el IPC de septiembre","url":"https://finance.yahoo.com/economy/policy/articles/feds-goolsbee-says-september-cpi-193440276.html"},{"label":"El d\xf3lar sube y el oro cae tras la inflaci\xf3n estadounidense","url":"https://finance.yahoo.com/markets/currencies/articles/dollar-ticks-gold-slides-on-us-inflation-news-193351444.html"},{"label":"Wall Street baja el mi\xe9rcoles por la aceleraci\xf3n inflacionaria","url":"https://www.interfax.ru/business/1122532"},{"label":"La inflaci\xf3n rusa del 6 al 12 de octubre es del 0,11%; la anual llega al 7,22%","url":"https://www.interfax.ru/business/1122459"},{"label":"Los precios suben un 0,11% del 6 al 12 de octubre","url":"https://www.vedomosti.ru/economics/news/2026/10/14/1237099-inflyatsiya-sostavila"}],"sourceBodySha256":"28f2c644ef71d7bb0798565c5d39754497c35d4acc2f2fb91243b4680ba43a81"}')}}]);